UPDATE run
   SET status = CAST(#{param3} AS run_status),
       actual_end = now()
 WHERE tenant_id = #{param1}
   AND id = #{param2}

UPDATE run
   SET exec_phase = 'SETTLED',
       updated_at = now()
 WHERE tenant_id = #{param1}
   AND id = #{param2}
   AND exec_phase <> 'SETTLED'

