UPDATE experiment_run
   -- experiment_run.status 是 varchar（只有 run.status 是 run_status 枚举），
   -- 这里不能加 ::experiment_run_status —— 该类型在库里不存在。
   SET status = #{param3},
       error = #{param4}
, finished_at = now()
 WHERE tenant_id = #{param1}
   AND id = #{param2}
   AND status NOT IN ('aborted', 'cancelled')

UPDATE run
   SET attendance = #{param3}
 WHERE tenant_id = #{param1}
   AND id = #{param2}
   AND status = 'running'
